func TestCleanCorpus(t *testing.T) {
	if len(corpus) < 60 {
		t.Fatalf("the corpus has %d names, want at least 60", len(corpus))
	}
	cases := make([]cleanCase, len(corpus))
	for i, c := range corpus {
		cases[i] = cleanCase{in: c.in, want: c.want, source: c.source}
	}
	runClean(t, cases)
}
